function validate([mass, asteroids]) {
  if (!Number.isInteger(mass) || mass < 1 || mass > 100000) return 'mass is an integer from 1 to 10^5.';
  if (asteroids.length < 1 || asteroids.length > 100000) return 'asteroids needs 1 to 10^5 values.';
  if (asteroids.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each asteroid mass is an integer from 1 to 10^5.';
  return null;
}

