function asteroidsDestroyed(mass, asteroids) {
  // Eating any asteroid the planet can handle never hurts, so keep eating until stuck.
  const left = asteroids.slice();
  let current = mass;
  let progress = true;
  while (left.length > 0 && progress) {
    progress = false;
    for (let i = 0; i < left.length; i++) {
      if (left[i] <= current) {
        current += left[i];
        left.splice(i, 1);
        progress = true;
        break;
      }
    }
  }
  return left.length === 0;
}

