function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const cap = large ? 100000 : 30;
  const mode = Math.floor(rand() * 3);
  const asteroids = [];
  let mass;
  if (mode === 0) {
    mass = 1 + Math.floor(rand() * (large ? 100000 : 20));
    for (let i = 0; i < n; i++) asteroids.push(1 + Math.floor(rand() * cap));
  } else {
    // A tight chain: each asteroid is just barely edible; mode 2 plants a wall that is one too heavy.
    mass = 1 + Math.floor(rand() * 3);
    let total = mass;
    const wallAt = mode === 2 ? Math.floor(rand() * Math.min(n, 16)) : -1;
    for (let i = 0; i < n; i++) {
      if (wallAt >= 0 && i >= wallAt) {
        asteroids.push(Math.min(cap, total + 1 + Math.floor(rand() * 3)));
      } else {
        const value = Math.max(1, Math.min(cap, total - Math.floor(rand() * 3)));
        asteroids.push(value);
        total += value;
      }
    }
  }
  for (let i = asteroids.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [asteroids[i], asteroids[j]] = [asteroids[j], asteroids[i]];
  }
  return [mass, asteroids];
}
